INSERT INTO careers (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-010000000001', 'backend-developer-go', 'Backend Developer con Go', 'De cero a producción: servicios HTTP, bases de datos y despliegue con Go.', 'Una carrera para convertirte en backend developer con Go. Empezás por el lenguaje, seguís por APIs y bases de datos, y terminás desplegando y observando servicios reales. Sin relleno: cada curso construye sobre el anterior.', 'medio', 12900, 'published', 1)
INSERT INTO careers (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-010000000002', 'datos-para-backend', 'Datos para backend', 'PostgreSQL a fondo, caches y colas: el lado de los datos de un backend serio.', 'Modelado, índices, transacciones y rendimiento en PostgreSQL, más Redis y colas de trabajo. Para quien ya programa y quiere que sus datos dejen de ser el cuello de botella.', 'intenso', 9900, 'published', 2)
INSERT INTO careers (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-010000000003', 'carrera-borrador', 'Carrera en borrador', 'No debería verse en el catálogo.', '', 'suave', 1000, 'draft', 3)
INSERT INTO courses (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-020000000001', 'go-desde-cero', 'Go desde cero', 'Sintaxis, tipos, errores, concurrencia y el toolchain, con la cabeza puesta en backend.', 'Aprendé Go como se usa en la industria: paquetes, structs e interfaces, manejo de errores idiomático, goroutines y channels, testing con la librería estándar. Terminás con un CLI y un servidor HTTP mínimos.', 'suave', 4900, 'published', 1)
INSERT INTO courses (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-020000000002', 'apis-rest-go-chi', 'APIs REST con Go y Chi', 'Diseño de APIs, routing, middleware, validación, auth y buenas prácticas de producción.', 'Construís una API completa con Chi: rutas, middleware, JSON, errores consistentes, autenticación con JWT, rate limiting y logging estructurado. Todo con tests.', 'medio', 5900, 'published', 2)
INSERT INTO courses (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-020000000003', 'postgresql-para-backends', 'PostgreSQL para backends', 'Modelado, índices, transacciones y rendimiento desde el punto de vista de la aplicación.', 'Dejá de tratar la base como una caja negra. Modelado relacional real, índices que sí se usan, transacciones y aislamiento, EXPLAIN, migraciones y acceso desde Go con pgx y sqlc.', 'medio', 5900, 'published', 3)
INSERT INTO courses (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-020000000004', 'go-en-produccion', 'Go en producción', 'Contenedores, observabilidad, despliegue y operación de servicios Go.', 'Dockerfiles multi-stage, configuración por entorno, métricas, trazas y logs, health checks, despliegue con cero downtime y qué mirar cuando algo se rompe a las 3 de la mañana.', 'intenso', 6900, 'published', 4)
INSERT INTO courses (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-020000000005', 'redis-y-colas', 'Redis y colas de trabajo', 'Cache, rate limiting y procesamiento en background con Redis desde Go.', 'Patrones de cache que no te muerden, estructuras de datos de Redis aplicadas, y colas de trabajo con reintentos, idempotencia y visibilidad.', 'intenso', 4900, 'published', 5)
INSERT INTO courses (id, slug, title, subtitle, description, level, price_cents, status, position) VALUES
  ('00000000-0000-4000-8000-020000000006', 'curso-borrador', 'Curso en borrador', 'No debería verse en el catálogo.', '', 'suave', 1000, 'draft', 6)
